import db from "App/db/db";

// Live annotations generated by the path array (« Calepinage ») of the given
// source annotations (`pathArraySourceAnnotationId`), ordered by source then
// by `pathArrayIndex`. `projectId` narrows the scan to one project (indexed);
// without it the whole table is filtered.
export default async function collectPathArrayChildren({
  sourceIds,
  projectId,
}) {
  const set = new Set((sourceIds ?? []).filter(Boolean));
  if (set.size === 0) return [];
  const collection = projectId
    ? db.annotations.where("projectId").equals(projectId)
    : db.annotations.toCollection();
  const children = await collection
    .filter((a) => !a.deletedAt && set.has(a.pathArraySourceAnnotationId))
    .toArray();
  return children.sort(
    (a, b) =>
      String(a.pathArraySourceAnnotationId).localeCompare(
        String(b.pathArraySourceAnnotationId)
      ) || (a.pathArrayIndex ?? 0) - (b.pathArrayIndex ?? 0)
  );
}
